from lib import *
S = SS('l43')
steps = [
    step("git 不记录改名。把 old.txt 改名为 new.txt 提交之后,两个提交的 tree 里只是文件名不同、blob 都是 c6f6b1d(同一个 hash)。git diff --name-status 显示 R100  old.txt  new.txt;加 --no-renames 则是 A new.txt 加 D old.txt。改名是比较两个 tree 时推断出来的:内容完全相同的文件 blob hash 相同,100% 的改名只要比 hash,不用比内容。", t=tl(S(1)), mark=lidx(S(1), 'R100', '--no-renames'), done=lidx(S(1), 'c6f6b1d6e95f', 'A\tnew.txt', 'D\told.txt'), kv=KV([['tree', '只记录文件名 → blob'], ['R100', '内容相同,比 hash 即可'], ['--no-renames', '关掉推断']], ['tree'])),
    step("10 个各 100 行的文件同时改名,并且把 0%~90% 的行改掉。默认阈值 50%(-M):相似度分数依次是 R100、R088、R077、R066、R056,改动 50% 的分数是 46%,低于阈值,被拆成 D+A。-M30% 把阈值降到 30%:改动 50% 的(R046)和 60% 的(R036)也识别为改名;-M70% 只认 R100、R088、R077;-M90% 只认 R100。分数不是“没改的行占比”那么简单:改了 10% 的行,分数是 88%,因为新内容的字节也算进总量里。", t=tl(S(2)), mark=lidx(S(2), '50%        D+A', '40%       R056', '60%        D+A'), done=lidx(S(2), '0%       R100', '10%       R088', '20%       R077', '30%       R066'), b=bars([['改动 0%', 100, '相似度 100'], ['改动 10%', 88, '88'], ['改动 20%', 77, '77'], ['改动 30%', 66, '66'], ['改动 40%', 56, '56'], ['改动 50%', 46, '46(低于 50 → D+A)'], ['改动 60%', 36, '36']], 100, mark=[5, 6], done=[0, 1, 2, 3, 4]), kv=KV([['默认阈值', '50%'], ['分数', '大约 100 − 1.1 × 改动百分比(本例)'], ['-M<n>%', '调整阈值']], ['默认阈值'])),
    step("没被识别成改名的后果:改名同时只改了少量内容(相似度 R093)的 doc.txt → manual.txt,git log -- manual.txt 只看到最后那一个提交“改名并大改”,而 git log --follow -- manual.txt 沿着改名一路追到“修改”“创建”共 3 个提交。而改名时改了 60% 的另一个例子,git diff 显示 D doc.txt 加 A manual.txt(不是改名),--follow 也只找到 1 个提交——历史在这里断了。", t=tl(S(3)), mark=lidx(S(3), '--- --follow:', 'R093', 'D\tdoc.txt'), done=lidx(S(3), '改名并大改', '修改', '创建', '改名并改了60%'), kv=KV([['log -- 路径', '不追改名'], ['log --follow', '沿相似度追到改名之前'], ['改动太大', '推断失败,历史断开']], ['log --follow'])),
    step("renameLimit:1200 个文件全部改名并轻微修改(d/ → e/),要比较 1200 × 1200 对。默认的 diff.renameLimit(1000)不够:git diff --name-status 得到 1200 个 A 和 1200 个 D,没有一个 R,并给出警告 exhaustive rename detection was skipped due to too many files 和 you may want to set your diff.renameLimit variable to at least 1200。用 -l2000 或 -c diff.renameLimit=2000,得到 1200 个 R,检测耗时 372 ms。", t=tl(S(4)), mark=lidx(S(4), '1200 A', '1200 D', 'exhaustive rename detection'), done=lidx(S(4), '1200 R', '-l2000 的检测耗时'), b=bars([['默认上限 1000', 0, '0 个 R(跳过检测)'], ['-l2000', 1200, '1200 个 R']], 1200, mark=[0], done=[1]), kv=KV([['diff.renameLimit', '默认 1000'], ['超过时', '放弃精确检测,只认 100% 相同'], ['代价', '1200 对要 372 ms']], ['diff.renameLimit'])),
    step("合并同样依赖相似度:一边把 doc.txt 改名为 manual.txt(改了 20% 的内容),另一边修改了 doc.txt 的一行。git merge 输出 Auto-merging manual.txt 和 CONFLICT (content): Merge conflict in manual.txt——改名被识别,修改应用到新名字上,只是内容冲突。把改名时的改动提高到 70%:git 认不出改名,报 CONFLICT (modify/delete): doc.txt deleted in ren and modified in HEAD。改名后的相似度太低,另一边的修改就变成“修改了一个被删除的文件”。", t=tl(S(5)), mark=lidx(S(5), '改动 70%', 'modify/delete'), done=lidx(S(5), '改动 20%', 'Auto-merging manual.txt'), kv=KV([['相似度够', '修改跟着改名走'], ['相似度不够', 'modify/delete 冲突'], ['建议', '改名和大改分成两个提交']], ['建议'])),
]
A = mkarti('l43', 43, 'Git,改名检测,rename,similarity,diff,真实验证,动画演示',
    '实测 git 的改名检测:tree 里只有文件名到 blob 的映射,改名是比较两个 tree 时推断的;内容相同的 R100 只比 hash;改名同时改 0%~90% 的行,相似度分数依次是 100、88、77、66、56、46、36,默认阈值 50% 把改动 50% 以上的拆成 D+A;-M<n>% 调阈值;git log 不加 --follow 会在改名处断开;diff.renameLimit 默认 1000,1200 个改名超过上限就全部检测失败;合并时相似度不够会变成 modify/delete 冲突。',
    'git 不记录“改名”,那 git status 里的 renamed 是怎么来的?相似度阈值默认是多少、实际分数怎么随改动量变化、什么时候会检测失败?这篇逐项实测,再看 git log --follow、diff.renameLimit 和合并时的影响。',
    [('50%', '默认的改名相似度阈值;改名同时改了一半的行,分数 46% 就被拆成 D+A'), ('R100 … R036', '改名同时改动 0%~60% 的行得到的相似度分数,每 10% 约降 11 分'), ('1000', 'diff.renameLimit 默认值,1200 个改名超过上限时一个都检测不出来')],
    [('改名是推断出来的', '<p>commit 的 tree 只记录“文件名 → blob”。改名只在比较两个 tree 时被推断:先把删掉的文件和新增的文件按 blob hash 配对(100% 相同,极快),剩下的再按内容相似度配对。</p>'),
     ('相似度', '<p>默认阈值 50%(<code>-M</code> 或 <code>-M50%</code>)。本例中改动 10% 的行,分数是 88%,每多改 10% 约降 11 分,改动 50% 时是 46%,低于阈值就被当成删除加新增。<code>-M30%</code> 放宽、<code>-M90%</code> 收紧。</p>'),
     ('历史会断', '<p><code>git log -- 路径</code> 不追改名,<code>--follow</code> 沿相似度向前追。如果改名时改动过大,推断失败,<code>--follow</code> 也追不到,历史在那里断开。</p>'),
     ('renameLimit', '<p>不精确检测要比较(删除 × 新增)的每一对,所以有上限 <code>diff.renameLimit</code>(默认 1000)。超过时 git 只认 100% 相同的改名并警告;调到 2000 之后 1200 个改名全部识别,用了约 372 ms。</p>'),
     ('合并', '<p>合并用同样的检测:另一边修改了旧名字时,识别出改名就把修改带到新名字上;识别不出就变成 modify/delete 冲突。把“改名”和“大改”分成两个提交可以避免这个问题。</p>')],
    steps,
    [ENV_I_GIT + '。测试文件是固定种子生成的随机文本(每个文件 100 行,每行 30 个随机字母),“改动 N% 的行”是把对应的行整行替换成新的随机内容;分数是 git diff --name-status 里的 R<分数>;耗时一次测量(含进程启动)',
     '没有验证:-C / -C -C 的复制检测;merge.renames 与 merge.directoryRenames(目录改名);二进制文件、很短的文件(几行)的分数行为;分数的精确算法(只从行为推断了大致关系);git blame -M / -C(见后面 blame 一篇)'],
    '改名检测')
